1	"use client";
2	
3	import { useState } from "react";
4	import { WebTerminal } from "@/components/customer/WebTerminal";
5	
6	/**
7	 * "Open terminal" button for the server detail page. Opens the shared
8	 * WebTerminal panel wired to this single server. Reuses the exact component
9	 * from the Claude Code hub — the `connect` field mirrors the hub's list shape.
10	 */
11	export function OpenTerminalButton({
12	  servers,
13	}: {
14	  servers: { id: string; hostname: string; connect: string }[];
15	}) {
16	  const [open, setOpen] = useState(false);
17	
18	  return (
19	    <>
20	      <button className="btn-secondary" onClick={() => setOpen(true)}>
21	        Open terminal
22	      </button>
23	      {open && (
24	        <WebTerminal
25	          servers={servers.map((s) => ({ id: s.id, hostname: s.hostname }))}
26	          onClose={() => setOpen(false)}
27	        />
28	      )}
29	    </>
30	  );
31	}
