1	"use client";
2	
3	import Link from "next/link";
4	import { usePathname } from "next/navigation";
5	import { useEffect, useState, useTransition } from "react";
6	import { CommandPalette } from "./CommandPalette";
7	import FeedbackWidget from "@/components/FeedbackWidget";
8	import VisitTracker from "@/components/VisitTracker";
9	import { logout } from "@/lib/actions";
10	import { markNotificationsRead, stopImpersonating } from "@/lib/actions-account";
11	
12	export type NavChild = { label: string; href: string; badge?: number };
13	export type NavItem = {
14	  label: string;
15	  href: string;
16	  /**
17	   * Leading icon. Optional: the customer portal gives every item an icon; the
18	   * admin portal renders flat section lists with no per-item icon, so the link
19	   * omits the icon when this is absent.
20	   */
21	  icon?: string;
22	  badge?: number;
23	  /**
24	   * Optional sub-items. When present the sidebar renders an expandable group:
25	   * the group whose child matches the current path is expanded (its children
26	   * shown as indented sub-links), every other group collapses to a header row.
27	   * Customer nav passes no children, so it renders exactly as a flat link.
28	   */
29	  children?: NavChild[];
30	};
31	export type NavSection = {
32	  label?: string;
33	  items: NavItem[];
34	};
35	
36	export type ShellNotification = {
37	  id: string;
38	  title: string;
39	  body?: string | null;
40	  href?: string | null;
41	  readAt: string | null;
42	  createdAt: string;
43	};
44	
