107	function Icon({ name }: { name: string }) {
108	  return (
109	    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
110	      {icons[name] ?? icons.folder}
111	    </svg>
112	  );
