114	
115	function Logo({ tag, collapsed }: { tag?: string; collapsed?: boolean }) {
116	  return (
117	    <Link href="/" className={`flex items-center gap-2.5 px-2 ${collapsed ? "lg:justify-center lg:px-0" : ""}`}>
118	      {/* eslint-disable-next-line @next/next/no-img-element */}
119	      <img
120	        src="/logo.png"
121	        alt="Nxeon"
122	        style={{ height: 40, width: "auto" }}
123	        className={`select-none object-contain ${collapsed ? "lg:hidden" : ""}`}
124	      />
125	      {/* Compact mark, shown only when the desktop rail is collapsed. */}
126	      {/* eslint-disable-next-line @next/next/no-img-element */}
127	      <img
128	        src="/favicon.svg"
129	        alt="Nxeon"
130	        style={{ height: 30, width: 30 }}
131	        className={`hidden select-none object-contain ${collapsed ? "lg:block" : ""}`}
132	      />
133	      {tag && (
134	        <span
135	          className={`rounded-md border border-amber-400/30 bg-amber-400/10 px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-widest text-amber-300 ${
136	            collapsed ? "lg:hidden" : ""
137	          }`}
138	        >
139	          {tag}
140	        </span>
141	      )}
142	    </Link>
143	  );
144	}
145	
146	export function Shell({
147	  nav,
148	  user,
149	  notifications,
150	  impersonation,
151	  tag,
152	  children,
153	}: {
154	  nav: NavSection[];
155	  user: { name: string; email: string; role: string; balanceCents: number };
156	  notifications: ShellNotification[];
157	  impersonation?: { adminName: string; targetEmail: string } | null;
158	  tag?: string;
159	  children: React.ReactNode;
160	}) {
161	  const pathname = usePathname();
162	  const [notifOpen, setNotifOpen] = useState(false);
163	  const [sidebarOpen, setSidebarOpen] = useState(false);
164	  // Desktop-only main-sidebar collapse. Persisted so it holds across every
165	  // portal page (mail, calendar, servers…). On mobile the drawer always renders
166	  // expanded — every collapse style below is gated to the `lg:` breakpoint.
167	  const [collapsed, setCollapsed] = useState(false);
168	  const [, startTransition] = useTransition();
169	
170	  useEffect(() => {
171	    try {
172	      if (localStorage.getItem("nxeon.portal.railCollapsed") === "1") setCollapsed(true);
173	    } catch {}
174	  }, []);
175	  function toggleCollapsed() {
176	    setCollapsed((c) => {
177	      const next = !c;
178	      try {
179	        localStorage.setItem("nxeon.portal.railCollapsed", next ? "1" : "0");
180	      } catch {}
181	      return next;
182	    });
183	  }
184	  const unread = notifications.filter((n) => !n.readAt).length;
185	
186	  // Flatten for the command palette: when a nav item has children, expose the
187	  // children (the real destinations) instead of the group header; flat items
188	  // (customer portal) pass through unchanged.
189	  const flatNav = nav.flatMap((s) =>
190	    s.items.flatMap((i) =>
191	      i.children && i.children.length > 0
192	        ? i.children.map((c) => ({ label: c.label, href: c.href, section: s.label }))
193	        : [{ label: i.label, href: i.href, section: s.label }]
194	    )
195	  );
196	
197	  // Longest-prefix match across every group's children, mirroring
198	  // groupForPath() in lib/admin-groups.ts. The single winning href both
199	  // highlights its sub-link and expands its parent group. Bare "/admin" only
200	  // matches exactly so it never swallows deeper routes.
201	  let activeChildHref: string | null = null;
202	  {
203	    let bestLen = -1;
204	    for (const section of nav) {
205	      for (const item of section.items) {
206	        for (const c of item.children ?? []) {
207	          const matches =
208	            c.href === pathname ||
209	            (c.href !== "/admin" && pathname.startsWith(c.href + "/"));
210	          if (matches && c.href.length > bestLen) {
211	            activeChildHref = c.href;
212	            bestLen = c.href.length;
213	          }
214	        }
215	      }
216	    }
217	  }
218	
219	  return (
220	    <div className="flex min-h-screen">
221	      <CommandPalette nav={flatNav} />
222	      <FeedbackWidget />
223	      <VisitTracker kind="portal" />
224	
225	      {/* Sidebar */}
226	      <aside
227	        className={`fixed inset-y-0 left-0 z-40 flex w-60 flex-col border-r border-white/[0.06] bg-navy-900/80 backdrop-blur-xl transition-all lg:static lg:translate-x-0 ${
228	          collapsed ? "lg:w-[4.75rem]" : "lg:w-60"
229	        } ${sidebarOpen ? "translate-x-0" : "-translate-x-full"}`}
230	      >
231	        <div className={`flex h-16 items-center px-4 ${collapsed ? "lg:justify-center lg:px-0" : ""}`}>
