37	function fmtUptime(seconds: number): string {
38	  if (!seconds || seconds <= 0) return "—";
39	  const d = Math.floor(seconds / 86400);
40	  const h = Math.floor((seconds % 86400) / 3600);
41	  const m = Math.floor((seconds % 3600) / 60);
42	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
43	}
