129	function PromptModal({ tmpl, onClose }: { tmpl: PromptTemplate; onClose: () => void }) {
130	  const [values, setValues] = useState<Record<string, string>>(
131	    Object.fromEntries(tmpl.placeholders.map((p) => [p.key, p.example]))
132	  );
133	  const filled = fill(tmpl.prompt, values);
134	
135	  // Render the prompt preview with the placeholder values highlighted.
136	  const preview = useMemo(() => {
137	    const parts: React.ReactNode[] = [];
138	    const re = /\{([A-Z0-9_]+)\}/g;
139	    let last = 0;
140	    let m: RegExpExecArray | null;
141	    let idx = 0;
142	    while ((m = re.exec(tmpl.prompt))) {
143	      if (m.index > last) parts.push(tmpl.prompt.slice(last, m.index));
144	      const v = values[m[1]]?.trim();
145	      parts.push(
146	        <mark key={idx++} className="rounded bg-brand-500/25 px-1 text-brand-100">
147	          {v || `{${m[1]}}`}
148	        </mark>
149	      );
150	      last = m.index + m[0].length;
151	    }
152	    if (last < tmpl.prompt.length) parts.push(tmpl.prompt.slice(last));
153	    return parts;
154	  }, [tmpl.prompt, values]);
155	
156	  const [mounted, setMounted] = useState(false);
