"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { headers } from "next/headers";
import bcrypt from "bcryptjs";
import { z } from "zod";
import { db } from "./db";
import {
  requireUser,
  requireAdmin,
  setImpersonation,
  clearImpersonation,
  createSession,
} from "./auth";
import { checkRateLimit } from "./rate-limit";

// ---------- Profile ----------

export async function updateProfile(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const name = String(formData.get("name") ?? "").trim();
  if (name.length < 1 || name.length > 100) return { error: "Enter a valid name." };
  await db.user.update({ where: { id: user.id }, data: { name } });
  revalidatePath("/dashboard/settings");
  return { ok: true };
}

export async function changePassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const current = String(formData.get("current") ?? "");
  const next = String(formData.get("next") ?? "");
  if (next.length < 8) return { error: "New password must be at least 8 characters." };
  if (!(await bcrypt.compare(current, user.passwordHash))) return { error: "Current password is incorrect." };
  // Bump sessionVersion to evict every other outstanding session, then re-issue a
  // fresh token for THIS session so the user who changed the password stays in.
  await db.user.update({
    where: { id: user.id },
    data: { passwordHash: await bcrypt.hash(next, 12), sessionVersion: { increment: 1 } },
  });
