"use server";

import { db } from "./db";
import { requireUser } from "./auth";

/**
 * Server list for the terminal dock's "+" server picker.
 *
 * Returns the calling user's RUNNING servers as {id, hostname}[]. Ownership is
 * enforced by the `userId` filter (admins see only their own here — opening a
 * shell still re-checks ownership when the token is minted). The websocket
 * itself is authorized separately by the short-lived token from
 * POST /api/terminal/token, so this action only feeds the picker UI.
 */
export async function listTerminalServers(): Promise<{ id: string; hostname: string }[]> {
  const user = await requireUser();
  return db.server.findMany({
    where: { userId: user.id, status: "RUNNING" },
    select: { id: true, hostname: true },
    orderBy: { createdAt: "desc" },
  });
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";
import type { Terminal as XTerm } from "@xterm/xterm";
import type { FitAddon as XFitAddon } from "@xterm/addon-fit";
import { listTerminalServers } from "@/lib/actions-terminal";
import "@xterm/xterm/css/xterm.css";

/**
 * Portal-wide, PERSISTENT terminal dock.
 *
 * The whole point of this component is that it is mounted ONCE, at the portal
 * shell level (components/portal/Shell.tsx). Because the App Router keeps Shell
 * mounted across in-portal navigation, the dock — and every live shell session
 * it holds — survives page changes. Navigating from /dashboard/servers/x to
 * /dashboard/build never unmounts the websocket, so a running `claude` build
 * keeps going.
 *
 * How sessions survive re-renders / route changes / minimize↔restore:
 *   - The tab bar is driven by `sessions` state (plain metadata: id, hostname,
 *     status) so the UI re-renders normally.
 *   - The LIVE objects for each session — the xterm `Terminal`, its `FitAddon`,
 *     the `WebSocket`, the `ResizeObserver`, and a PERSISTENT container <div> —
 *     live in a `Map` ref (`liveRef`). Refs are never recreated by React, so
 *     these objects (and the socket) outlive every render.
 *   - Each session's xterm is attached to its own persistent container div
 *     (created once, stored in the ref). The dock renders one mount slot per
 *     session and appends that same div into it via a ref callback. Switching
 *     the active tab just toggles `display`; the hidden sessions keep their
 *     sockets open in the background. Toggling maximize↔minimize only changes
 *     the OUTER wrapper's size/position classes — the surface holding the
 *     containers keeps the same DOM nodes, so xterm/scrollback/socket are never
 *     recreated.
 *
 * Wire protocol + connection logic are reused verbatim from the old
 * components/customer/WebTerminal.tsx (token → wss /terminal-ws → JSON
 * {type:"data"|"resize"} up, raw output down).
 */

export type TerminalServerRef = { id: string; hostname: string };

type Status = "connecting" | "connected" | "closed" | "error";
type Mode = "hidden" | "maximized" | "minimized";

type SessionMeta = { id: string; hostname: string; status: Status };

type LiveSession = {
  id: string;
  hostname: string;
  container: HTMLDivElement;
  term: XTerm | null;
  fit: XFitAddon | null;
  ws: WebSocket | null;
  ro: ResizeObserver | null;
  starting: boolean;
};

type DockApi = {
  openSession: (server: TerminalServerRef) => void;
  focusSession: (id: string) => void;
  closeSession: (id: string) => void;
  minimize: () => void;
  restore: () => void;
  close: () => void;
};

const DockContext = createContext<DockApi | null>(null);

/** Hook exposing the dock controls to any client component inside Shell. */
export function useTerminalDock(): DockApi {
  const ctx = useContext(DockContext);
  if (!ctx) throw new Error("useTerminalDock must be used within <TerminalDockProvider>");
  return ctx;
}

/* -------------------------------------------------------------------------- */
/* Provider — owns all state + the live-session ref map + the dock controls    */
/* -------------------------------------------------------------------------- */

export function TerminalDockProvider({ children }: { children: React.ReactNode }) {
  const [sessions, setSessions] = useState<SessionMeta[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [mode, setMode] = useState<Mode>("hidden");
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Live xterm/ws/container objects, keyed by server id. Never recreated by
  // React — this is what makes sessions survive navigation and re-renders.
  const liveRef = useRef<Map<string, LiveSession>>(new Map());

  const setStatus = useCallback((id: string, status: Status) => {
    setSessions((prev) => prev.map((s) => (s.id === id ? { ...s, status } : s)));
  }, []);

  const fitAndResize = useCallback((id: string) => {
    const live = liveRef.current.get(id);
    if (!live || !live.term || !live.fit) return;
    try {
      live.fit.fit();
    } catch {
      /* ignore */
    }
    const ws = live.ws;
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify({ type: "resize", cols: live.term.cols, rows: live.term.rows }));
    }
  }, []);

  /** Build the xterm + websocket for a session whose container is in the DOM. */
  const connect = useCallback(
    async (id: string) => {
      const live = liveRef.current.get(id);
      if (!live || live.starting || live.term) return;
      live.starting = true;
      setStatus(id, "connecting");
      setErrors((e) => {
        if (!e[id]) return e;
        const next = { ...e };
        delete next[id];
        return next;
      });

      // 1. Mint a short-lived token (session + ownership checked server-side).
      let token: string;
      try {
        const res = await fetch("/api/terminal/token", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ serverId: id }),
        });
        const body = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(body?.error || "Could not authorize the terminal.");
        token = body.token;
        if (!token) throw new Error("No terminal token was issued.");
      } catch (e) {
        live.starting = false;
        setStatus(id, "error");
        setErrors((prev) => ({
          ...prev,
          [id]: e instanceof Error ? e.message : "Could not authorize the terminal.",
        }));
        return;
      }
      if (!liveRef.current.has(id)) return; // closed while awaiting

      // 2. Build the terminal into the session's persistent container.
      const [{ Terminal }, { FitAddon }] = await Promise.all([
        import("@xterm/xterm"),
        import("@xterm/addon-fit"),
      ]);
      if (!liveRef.current.has(id)) return;

      const term = new Terminal({
        cursorBlink: true,
        fontFamily:
          'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace',
        fontSize: 13,
        theme: { background: "#0a0e1a", foreground: "#e2e8f0", cursor: "#e2e8f0" },
      });
      const fit = new FitAddon();
      term.loadAddon(fit);
      term.open(live.container);
      try {
        fit.fit();
      } catch {
        /* ignore */
      }
      live.term = term;
      live.fit = fit;

      // 3. Open the websocket to the PTY backend (nginx proxies /terminal-ws).
      const scheme = location.protocol === "https:" ? "wss" : "ws";
      const ws = new WebSocket(
        `${scheme}://${location.host}/terminal-ws?token=${encodeURIComponent(token)}`
      );
      ws.binaryType = "arraybuffer";
      live.ws = ws;

      ws.onopen = () => {
        setStatus(id, "connected");
        term.focus();
        fitAndResize(id);
      };
      ws.onmessage = (ev) => {
        if (typeof ev.data === "string") {
          term.write(ev.data);
        } else if (ev.data instanceof ArrayBuffer) {
          term.write(new Uint8Array(ev.data));
        }
      };
      ws.onerror = () => {
        setErrors((prev) => ({ ...prev, [id]: "Connection error." }));
      };
      ws.onclose = (ev) => {
        setStatus(id, "closed");
        if (ev.reason && live.term) {
          term.write(`\r\n\x1b[90m[${ev.reason}]\x1b[0m\r\n`);
        }
      };

      // 4. Keystrokes → server.
      term.onData((data) => {
        if (ws.readyState === WebSocket.OPEN) {
          ws.send(JSON.stringify({ type: "data", data }));
        }
      });

      // 5. Keep the PTY window sized to the visible surface.
      const ro = new ResizeObserver(() => fitAndResize(id));
      ro.observe(live.container);
      live.ro = ro;
    },
    [fitAndResize, setStatus]
  );

  /** Tear down a session's live socket + xterm (idempotent). */
  const teardownLive = useCallback((live: LiveSession) => {
    try {
      live.ro?.disconnect();
    } catch {
      /* ignore */
    }
    live.ro = null;
    try {
      live.ws?.close();
    } catch {
      /* ignore */
    }
    live.ws = null;
    try {
      live.term?.dispose();
    } catch {
      /* ignore */
    }
    live.term = null;
    live.fit = null;
    try {
      live.container.remove();
    } catch {
      /* ignore */
    }
  }, []);

  /* ------------------------------- controls ------------------------------- */

  const openSession = useCallback((server: TerminalServerRef) => {
    const map = liveRef.current;
    if (map.has(server.id)) {
      // Already a tab — focus it instead of duplicating.
      setActiveId(server.id);
      setMode("maximized");
      return;
    }
    const container = document.createElement("div");
    container.className = "h-full w-full";
    map.set(server.id, {
      id: server.id,
      hostname: server.hostname,
      container,
      term: null,
      fit: null,
      ws: null,
      ro: null,
      starting: false,
    });
    setSessions((prev) => [...prev, { id: server.id, hostname: server.hostname, status: "connecting" }]);
    setActiveId(server.id);
    setMode("maximized");
  }, []);

  const focusSession = useCallback((id: string) => {
    setActiveId(id);
    setMode((m) => (m === "minimized" ? "minimized" : "maximized"));
  }, []);

  const closeSession = useCallback(
    (id: string) => {
      const live = liveRef.current.get(id);
      if (live) teardownLive(live);
      liveRef.current.delete(id);
      setErrors((prev) => {
        if (!prev[id]) return prev;
        const next = { ...prev };
        delete next[id];
        return next;
      });
      setSessions((prev) => {
        const next = prev.filter((s) => s.id !== id);
        if (next.length === 0) {
          setMode("hidden");
          setActiveId(null);
        } else {
          setActiveId((a) => (a === id ? next[0].id : a));
        }
        return next;
      });
    },
    [teardownLive]
  );

  const minimize = useCallback(() => setMode("minimized"), []);
  const restore = useCallback(() => setMode("maximized"), []);

  const close = useCallback(() => {
    for (const live of liveRef.current.values()) teardownLive(live);
    liveRef.current.clear();
    setSessions([]);
    setActiveId(null);
    setErrors({});
    setMode("hidden");
  }, [teardownLive]);

  /** Reconnect a session in place (keeps its tab + persistent container). */
  const reconnect = useCallback(
    (id: string) => {
      const live = liveRef.current.get(id);
      if (!live) return;
      try {
        live.ro?.disconnect();
      } catch {
        /* ignore */
      }
      live.ro = null;
      try {
        live.ws?.close();
      } catch {
        /* ignore */
      }
      live.ws = null;
      try {
        live.term?.dispose();
      } catch {
        /* ignore */
      }
      live.term = null;
      live.fit = null;
      live.starting = false;
      live.container.innerHTML = "";
      void connect(id);
    },
    [connect]
  );

  /** Mount slot: append the session's persistent container, kick off connect. */
  const attach = useCallback(
    (id: string, el: HTMLDivElement | null) => {
      const live = liveRef.current.get(id);
      if (!live || !el) return; // on unmount (el === null) we keep the container alive
      if (live.container.parentElement !== el) {
        el.appendChild(live.container);
      }
      if (!live.term && !live.starting) void connect(id);
    },
    [connect]
  );

  // Refit the active session whenever it becomes visible or the dock resizes.
  useEffect(() => {
    if (!activeId || mode === "hidden") return;
    const raf = requestAnimationFrame(() => fitAndResize(activeId));
    return () => cancelAnimationFrame(raf);
  }, [activeId, mode, fitAndResize]);

  const api: DockApi = {
    openSession,
    focusSession,
    closeSession,
    minimize,
    restore,
    close,
  };

  return (
    <DockContext.Provider value={api}>
      {children}
      <TerminalDock
        sessions={sessions}
        activeId={activeId}
        mode={mode}
        errors={errors}
        attach={attach}
        focusSession={focusSession}
        closeSession={closeSession}
        openSession={openSession}
        minimize={minimize}
        restore={restore}
        close={close}
        reconnect={reconnect}
      />
    </DockContext.Provider>
  );
}

/* -------------------------------------------------------------------------- */
/* Dock UI                                                                     */
/* -------------------------------------------------------------------------- */

const STATUS_COLOR: Record<Status, string> = {
  connecting: "bg-amber-400 animate-pulse",
  connected: "bg-emerald-400",
  closed: "bg-slate-500",
  error: "bg-red-500",
};

function IconBtn({
  onClick,
  label,
  children,
}: {
  onClick: () => void;
  label: string;
  children: React.ReactNode;
}) {
  return (
    <button
      onClick={onClick}
      aria-label={label}
      title={label}
      className="rounded-lg p-1.5 text-slate-400 transition-colors hover:bg-white/10 hover:text-white"
    >
      {children}
    </button>
  );
}

function TerminalDock({
  sessions,
  activeId,
  mode,
  errors,
  attach,
  focusSession,
  closeSession,
  openSession,
  minimize,
  restore,
  close,
  reconnect,
}: {
  sessions: SessionMeta[];
  activeId: string | null;
  mode: Mode;
  errors: Record<string, string>;
  attach: (id: string, el: HTMLDivElement | null) => void;
  focusSession: (id: string) => void;
  closeSession: (id: string) => void;
  openSession: (server: TerminalServerRef) => void;
  minimize: () => void;
  restore: () => void;
  close: () => void;
  reconnect: (id: string) => void;
}) {
  const [pickerOpen, setPickerOpen] = useState(false);
  const [pickerLoading, setPickerLoading] = useState(false);
  const [pickerServers, setPickerServers] = useState<TerminalServerRef[]>([]);
  const [pickerError, setPickerError] = useState<string | null>(null);
  const minimized = mode === "minimized";

  const activeMeta = sessions.find((s) => s.id === activeId) ?? null;

  const loadPicker = useCallback(async () => {
    setPickerLoading(true);
    setPickerError(null);
    try {
      const all = await listTerminalServers();
      setPickerServers(all);
    } catch {
      setPickerError("Could not load your servers.");
    } finally {
      setPickerLoading(false);
    }
  }, []);

  function togglePicker() {
    setPickerOpen((v) => {
      const next = !v;
      if (next) void loadPicker();
      return next;
    });
  }

  // Servers not already open as tabs.
  const openIds = new Set(sessions.map((s) => s.id));
  const pickable = pickerServers.filter((s) => !openIds.has(s.id));

  if (mode === "hidden" || sessions.length === 0) return null;

  const outerClass = minimized
    ? "fixed bottom-4 left-1/2 z-[65] flex h-[280px] w-[460px] max-w-[92vw] -translate-x-1/2 flex-col overflow-hidden rounded-2xl border border-white/10 bg-navy-900 shadow-2xl shadow-black/50"
    : "fixed inset-x-0 bottom-0 z-[70] flex h-[70vh] max-h-[82vh] flex-col overflow-hidden border-t border-white/10 bg-navy-900 shadow-2xl shadow-black/50 lg:left-60 lg:rounded-t-2xl lg:border-l";

  return (
    <div className={outerClass} role="dialog" aria-label="Terminal dock">
      {/* Header + tab bar */}
      <div className="flex flex-none items-center gap-1.5 border-b border-white/[0.06] bg-white/[0.02] px-2 py-1.5">
        {/* Tabs */}
        <div className="flex min-w-0 flex-1 items-center gap-1 overflow-x-auto">
          {sessions.map((s) => {
            const active = s.id === activeId;
            return (
              <div
                key={s.id}
                className={`group flex flex-none items-center gap-1.5 rounded-lg border px-2.5 py-1.5 text-xs transition-colors ${
                  active
                    ? "border-white/15 bg-white/10 text-white"
                    : "border-transparent bg-transparent text-slate-400 hover:bg-white/[0.06] hover:text-slate-200"
                }`}
              >
                <button
                  onClick={() => focusSession(s.id)}
                  className="flex min-w-0 items-center gap-1.5"
                  title={s.hostname}
                >
                  <span className={`h-2 w-2 flex-none rounded-full ${STATUS_COLOR[s.status]}`} />
                  <span className="max-w-[8rem] truncate font-medium">{s.hostname}</span>
                </button>
                <button
                  onClick={() => closeSession(s.id)}
                  aria-label={`Close ${s.hostname}`}
                  className="flex-none rounded p-0.5 text-slate-500 hover:bg-white/10 hover:text-white"
                >
                  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round">
                    <path d="M18 6 6 18M6 6l12 12" />
                  </svg>
                </button>
              </div>
            );
          })}

          {/* "+" add-a-server picker */}
          {!minimized && (
            <div className="relative flex-none">
              <IconBtn onClick={togglePicker} label="Connect another server">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                  <path d="M12 5v14M5 12h14" />
                </svg>
              </IconBtn>
              {pickerOpen && (
                <div className="absolute left-0 top-9 z-10 w-64 overflow-hidden rounded-xl border border-white/10 bg-navy-900 shadow-2xl shadow-black/50">
                  <p className="border-b border-white/[0.06] px-3 py-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500">
                    Open another server
                  </p>
                  <div className="max-h-56 overflow-y-auto py-1">
                    {pickerLoading ? (
                      <p className="px-3 py-3 text-xs text-slate-400">Loading…</p>
                    ) : pickerError ? (
                      <p className="px-3 py-3 text-xs text-red-300">{pickerError}</p>
                    ) : pickable.length === 0 ? (
                      <p className="px-3 py-3 text-xs text-slate-400">
                        No other running servers.
                      </p>
                    ) : (
                      pickable.map((s) => (
                        <button
                          key={s.id}
                          onClick={() => {
                            openSession(s);
                            setPickerOpen(false);
                          }}
                          className="flex w-full items-center gap-2 px-3 py-2 text-left text-xs text-slate-200 hover:bg-white/[0.06]"
                        >
                          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
                            <rect x="3" y="4" width="18" height="7" rx="2" />
                            <rect x="3" y="13" width="18" height="7" rx="2" />
                          </svg>
                          <span className="truncate">{s.hostname}</span>
                        </button>
                      ))
                    )}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Right controls */}
        <div className="flex flex-none items-center gap-0.5">
          {minimized ? (
            <IconBtn onClick={restore} label="Expand terminal">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7" />
              </svg>
            </IconBtn>
          ) : (
            <IconBtn onClick={minimize} label="Minimize terminal">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                <path d="M5 12h14" />
              </svg>
            </IconBtn>
          )}
          <IconBtn onClick={close} label="Close terminal dock">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <path d="M18 6 6 18M6 6l12 12" />
            </svg>
          </IconBtn>
        </div>
      </div>

      {/* Terminal surface — every session container lives here at once; only the
          active one is shown. This subtree keeps the SAME nodes across
          minimize↔restore so xterm/socket are never recreated. */}
      <div className="relative min-h-0 flex-1 bg-[#0a0e1a] p-1.5">
        {sessions.map((s) => (
          <div
            key={s.id}
            ref={(el) => attach(s.id, el)}
            className="absolute inset-1.5"
            style={{ display: s.id === activeId ? "block" : "none" }}
          />
        ))}
      </div>

      {/* Reconnect strip for the active session when its socket dropped. */}
      {activeMeta && (activeMeta.status === "closed" || activeMeta.status === "error") && (
        <div className="flex flex-none items-center gap-3 border-t border-white/[0.06] bg-white/[0.02] px-3 py-1.5 text-xs">
          <span className={activeMeta.status === "error" ? "text-red-300" : "text-slate-400"}>
            {errors[activeMeta.id] || (activeMeta.status === "error" ? "Error" : "Disconnected")}
          </span>
          <button
            onClick={() => reconnect(activeMeta.id)}
            className="ml-auto rounded-lg border border-white/10 bg-white/5 px-2.5 py-1 font-semibold text-slate-200 hover:bg-white/10"
          >
            Reconnect
          </button>
        </div>
      )}
    </div>
  );
}

