input.content:
"use client";

import { useTerminalDock } from "@/components/customer/terminal/TerminalDock";

/**
 * "Open terminal" trigger. A thin button that opens (or focuses) a session in
 * the portal-wide, PERSISTENT terminal dock (components/customer/terminal/
 * TerminalDock.tsx). It no longer mounts its own terminal, so the shell session
 * survives page navigation — the user can leave this page and the socket stays
 * connected. Opens the first server; more can be added from the dock's "+".
 */
export function OpenTerminalButton({
  servers,
  label = "Open terminal",
  className = "btn-secondary",
}: {
  servers: { id: string; hostname: string; connect?: string }[];
  label?: string;
  className?: string;
}) {
  const { openSession } = useTerminalDock();
  const first = servers[0];

  return (
    <button
      className={className}
      disabled={!first}
      onClick={() => first && openSession({ id: first.id, hostname: first.hostname })}
    >
      {label}
    </button>
  );
}

